    .skill-option input[type='checkbox']:checked,
    .skill-option input[type='radio']:checked {
      box-shadow: 0 0 5px rgba(120, 90, 78, 0.4);
    }

    .random-button {
      width: 100%;
      padding: 8px;
      margin-bottom: 10px;
      font-family: var(--font-body);
      font-weight: 500;
      font-size: 1em;
      color: var(--title-color);
      background-color: var(--button-bg-color);
      border: 1px solid var(--border-color-strong);
      border-radius: 0;
      cursor: pointer;
      text-align: center;
      transition: all 0.2s ease;
    }

    .random-button:hover {
      background-color: #c6b8a5;
    }

    .selection-control {
      display: flex;
      flex-direction: column;
      gap: 8px;
    }

    .selection-btn {
      padding: 10px 12px;
      font-family: var(--font-body);
      font-weight: 500;
      font-size: 1em;
      color: var(--title-color);
      background-color: var(--input-bg-color);
      border: 1px solid var(--border-color-light);
      border-radius: 0;
      cursor: pointer;
      text-align: left;
      transition: all 0.2s ease;
    }

    .selection-btn:hover {
      border-color: var(--border-color-strong);
      background-color: #e8e0d5;
    }

    .selection-summary {
      font-size: 0.85em;
      color: var(--text-color);
      padding-left: 5px;
    }

    .submit-button {
      width: 100%;
      padding: 12px;
      margin-top: 10px;
      font-family: var(--font-title);
      font-weight: 700;
      font-size: 1.2em;
      color: var(--title-color);
      background-color: var(--button-bg-color);
      border: 1px solid var(--border-color-strong);
      border-radius: 0;
      cursor: pointer;
      text-align: center;
      transition: all 0.2s ease;
    }

    .submit-button:hover {
      background-color: #c6b8a5;
      transform: translateY(-2px);
    }

    .rarity-common {
      color: #6c757d;
    }

    .rarity-uncommon {
      color: #4caf50;
    }

    .rarity-rare {
      color: #2196f3;
    }

    .rarity-epic {
      color: #9c27b0;
    }

    .rarity-legendary {
      color: #ffc107;
    }

    .rarity-mythic {
      color: #f44336;
    }

    .skill-main-info .rarity-common,
    .skill-main-info .rarity-uncommon,
    .skill-main-info .rarity-rare,
    .skill-main-info .rarity-epic,
    .skill-main-info .rarity-legendary,
    .skill-main-info .rarity-mythic {
      font-weight: bold;
    }

    .modal {
      display: none;
      position: fixed;
      z-index: 1000;
      left: 0;
      top: 0;
      width: 100%;
      height: 100%;
      overflow: auto;
      background-color: rgba(0, 0, 0, 0.6);
      animation: fadeIn 0.3s;
    }

    .modal-content {
      background-color: var(--bg-color);
      margin: 5% auto;
      padding: 25px;
      border: 2px solid var(--border-color-strong);
      width: 90%;
      max-width: 600px;
      position: relative;
      animation: slideIn 0.3s;
    }

    .modal-header {
      display: flex;
      justify-content: space-between;
      align-items: center;
      margin-bottom: 20px;
    }

    .modal-title {
      font-family: var(--font-title);
      font-size: 1.5em;
      color: var(--title-color);
      margin: 0;
    }

    .close-btn {
      color: var(--text-color);
      float: right;
      font-size: 28px;
      font-weight: bold;
      cursor: pointer;
    }

    .close-btn:hover,
    .close-btn:focus {
      color: var(--points-color);
      text-decoration: none;
    }

    .modal-options-list {
      display: flex;
      flex-direction: column;
      gap: 10px;
      max-height: 55vh;
      overflow-y: auto;
      padding-right: 10px;
    }

    .modal-footer {
      margin-top: 20px;
      text-align: right;
    }

    .modal-confirm-btn {
      padding: 10px 20px;
      font-family: var(--font-body);
      font-weight: 700;
      font-size: 1em;
      color: var(--title-color);
      background-color: var(--button-bg-color);
      border: 1px solid var(--border-color-strong);
      cursor: pointer;
      transition: background-color 0.2s;
    }

    .modal-confirm-btn:hover {
      background-color: #c6b8a5;
    }

    @keyframes fadeIn {
      from {
        opacity: 0;
      }

      to {
        opacity: 1;
      }
    }

    @keyframes slideIn {
      from {
        transform: translateY(-30px);
        opacity: 0;
      }

      to {
        transform: translateY(0);
        opacity: 1;
      }
    }


    @media (max-width: 600px) {
      body {
        padding: 10px;
      }

      .creator-scroll {
        padding: 20px;
      }

      .main-title {
        font-size: 1.5em;
      }

