    { name: '防护项链', type: '饰品', cost: 19, rarity: 'uncommon', description: '银链悬挂着一个经过圣水净化的微缩盾牌吊坠，附魔格挡+1，能自动格挡一次微弱的物理伤害，挂于颈部。' },
