    <script>
        document.addEventListener('DOMContentLoaded', () => {
            const dataInput = document.getElementById('data-input');
            const itemListContainer = document.getElementById('item-list-container');
            const detailWrapper = document.getElementById('item-detail-wrapper');
            const detailPlaceholder = document.getElementById('detail-placeholder');
            const detailError = document.getElementById('detail-error');
            const detailContentArea = document.getElementById('detail-content-area');
            const categoryButtons = document.querySelectorAll('.category-btn');

            // <<< 已修正: 引入新的映射函数，逻辑更清晰、健壮 >>>
            function mapTypeToCategoryKey(typeString) {
                if (typeString.includes('消耗品')) return 'consumable';
                if (typeString.includes('功能')) return 'functional';
                if (typeString.includes('特殊服务')) return 'special';
                // 可以为未来未知类型提供一个默认分类
                return 'other'; 
            }

            function initializeShop(xmlData) {
                const items = parseItemsFromXML(xmlData);
                if (items.length > 0) {
                    displayItemsList(items);
                    setupCategoryFilters();
                    clearDetailView();
                } else {
                    showError();
                }
            }

            function parseItemsFromXML(xmlData) {
                const parsedItems = [];
                const itemRegex = /<道具>([\s\S]*?)<\/道具>/g; let match;
                while ((match = itemRegex.exec(xmlData)) !== null) {
                    const itemBlock = match[1];
                    const nameMatch = itemBlock.match(/<道具名>([\s\S]*?)<\/道具名>/);
                    const typeMatch = itemBlock.match(/<道具类型>([\s\S]*?)<\/道具类型>/);
                    const priceMatch = itemBlock.match(/<道具价格>([\s\S]*?)<\/道具价格>/);
                    const effectMatch = itemBlock.match(/<道具效果>([\s\S]*?)<\/道具效果>/);
                    const commentaryMatch = itemBlock.match(/<莉莉丝的推销词>([\s\S]*?)<\/莉莉丝的推销词>/);
                    if (nameMatch && priceMatch) {
                        const originalType = typeMatch ? typeMatch[1].trim() : '其他';
                        // <<< 已修正: 调用映射函数得到分类键，不再手动处理字符串 >>>
                        const categoryKey = mapTypeToCategoryKey(originalType);

                        parsedItems.push({
                            id: `item-${parsedItems.length}`, 
                            name: nameMatch[1].trim(),
                            type: categoryKey, // 用于筛选的键
                            originalType: originalType, // 用于显示的原始文本
                            price: priceMatch[1].trim(), 
                            effect: effectMatch ? effectMatch[1].trim() : '无',
                            commentary: commentaryMatch ? commentaryMatch[1].trim() : '莉莉丝今天心情不错，这个好东西就直接卖给你吧。'
                        });
                    }
                }
                return parsedItems;
            }

            function displayItemsList(items) {
                itemListContainer.innerHTML = '';
                items.forEach(item => {
                    const card = document.createElement('div');
                    card.className = 'item-card';
                    card.id = item.id;
                    card.dataset.type = item.type; // 这里存入的是 'consumable', 'functional' 等键
                    card.innerHTML = `<div class="item-name">${item.name}</div><div class="item-price">${item.price}</div>`;
                    card.addEventListener('click', () => {
                        displayItemDetail(item);
                        document.querySelectorAll('.item-card').forEach(c => c.classList.remove('active'));
                        card.classList.add('active');
                    });
                    itemListContainer.appendChild(card);
                });
            }

            function displayItemDetail(item) {
                detailPlaceholder.style.display = 'none';
                detailError.style.display = 'none';
                detailContentArea.style.display = 'flex';
                detailContentArea.innerHTML = `
                    <div class="detail-header">
                        <div class="detail-name">${item.name}</div>
                        <div class="detail-price">${item.price}</div>
                    </div>
                    <div class="detail-section">
                        <div class="detail-label">道具类型</div>
                        <div class="detail-value">${item.originalType}</div>
                    </div>
                    <div class="detail-section">
                        <div class="detail-label">道具效果</div>
                        <div class="detail-value">${item.effect}</div>
                    </div>
                    <div class="detail-section">
                        <div class="detail-label">莉莉丝的推销词</div> 
                        <div class="detail-value commentary">${item.commentary}</div>
                    </div>`;
            }

            function setupCategoryFilters() {
                categoryButtons.forEach(button => {
                    button.addEventListener('click', () => {
                        const category = button.dataset.category;
                        categoryButtons.forEach(btn => btn.classList.remove('active'));
                        button.classList.add('active');
                        const allItemCards = document.querySelectorAll('.item-card');
                        allItemCards.forEach(card => {
                            // <<< 已修正: "全部"按钮的键现在是 "all" >>>
                            if (category === 'all' || card.dataset.type === category) {
                                card.classList.remove('hidden');
                            } else {
                                card.classList.add('hidden');
                            }
                        });
                        clearDetailView();
                    });
                });
            }

            function clearDetailView(){
                detailContentArea.style.display = 'none';
                detailError.style.display = 'none';
                detailPlaceholder.style.display = 'block';
                detailPlaceholder.innerHTML = '<p>← 从列表中选择一个道具查看详情</p>';
                document.querySelectorAll('.item-card').forEach(c => c.classList.remove('active'));
            }

            function showError() {
                detailContentArea.style.display = 'none';
                detailPlaceholder.style.display = 'none';
                detailError.style.display = 'block';
            }

            const interval = 50, timeout = 2000; let elapsedTime = 0;
            const dataObserver = setInterval(() => {
                const rawData = dataInput.value;
                elapsedTime += interval;
                if (rawData && rawData.trim() !== '$' + '1') {
                    clearInterval(dataObserver);
                    initializeShop(rawData);
                } else if (elapsedTime >= timeout) {
                    clearInterval(dataObserver);
                    showError();
                }
            }, interval);
        });
    </script>
</body>
