      color: var(--points-color);
      text-decoration: none;
    }

    .modal-options-list {
      display: flex;
      flex-direction: column;
      gap: 10px;
      max-height: 55vh;
      overflow-y: auto;
      padding-right: 10px;
    }

    .modal-footer {
      margin-top: 20px;
      text-align: right;
    }

    .modal-confirm-btn {
      padding: 10px 20px;
      font-family: var(--font-body);
      font-weight: 700;
      font-size: 1em;
      color: var(--title-color);
      background-color: var(--button-bg-color);
      border: 1px solid var(--border-color-strong);
      cursor: pointer;
      transition: background-color 0.2s;
    }

    .modal-confirm-btn:hover {
      background-color: #c6b8a5;
    }

    @keyframes fadeIn {
      from {
        opacity: 0;
      }

      to {
        opacity: 1;
      }
    }

    @keyframes slideIn {
      from {
        transform: translateY(-30px);
        opacity: 0;
      }

      to {
        transform: translateY(0);
        opacity: 1;
      }
    }


    @media (max-width: 600px) {
      body {
        padding: 10px;
      }

      .creator-scroll {
        padding: 20px;
      }

      .main-title {
        font-size: 1.5em;
